#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# Wizard chạy BÊN TRONG WSL (Ubuntu). Repo nằm trên ổ D của Windows nên đường dẫn trong WSL dạng /mnt/d/...
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
LAB_DIR="$REPO_ROOT/labs/03-cluster"
KT=/opt/kafka/bin/kafka-topics.sh
BOOT=kafka-1:19092
DOCKER=(docker)

banner "Bài 3: Docker Engine + cụm Kafka 3 broker trong WSL2"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Kiểm tra WSL2, Ubuntu 24.04 và systemd"
say "Wizard phải chạy trong cửa sổ Ubuntu (WSL), không phải PowerShell."
if ! grep -qi microsoft /proc/version 2>/dev/null; then
  warn "Không thấy dấu hiệu đang chạy trong WSL."
  confirm "Vẫn tiếp tục?" || exit 1
fi
# shellcheck disable=SC1091
. /etc/os-release
say "Hệ điều hành: ${PRETTY_NAME:-không rõ}"
if [[ "${VERSION_ID:-}" != "24.04" ]]; then
  warn "Hướng dẫn này kiểm chứng cho Ubuntu 24.04; máy bạn là ${VERSION_ID:-không rõ}."
  confirm "Vẫn tiếp tục?" || exit 1
fi
if [[ "$(ps -p 1 -o comm= 2>/dev/null || true)" == "systemd" ]]; then
  say "systemd đang chạy ✓"
else
  warn "systemd chưa chạy. Docker Engine cần nó để tự khởi động."
  step "Cần thêm vào /etc/wsl.conf:   [boot]  systemd=true"
  note "Nguồn: https://learn.microsoft.com/en-us/windows/wsl/wsl-config"
  if grep -q '^\[boot\]' /etc/wsl.conf 2>/dev/null; then
    warn "/etc/wsl.conf đã có mục [boot]. Hãy tự thêm dòng  systemd=true  rồi chạy lại wizard."
    exit 1
  fi
  confirm "Ghi vào /etc/wsl.conf bây giờ (cần sudo)?" || exit 1
  printf '\n[boot]\nsystemd=true\n' | sudo tee -a /etc/wsl.conf >/dev/null
  say "Đã ghi. Việc bạn cần làm tiếp:"
  step "Mở Windows PowerShell và chạy:  wsl.exe --shutdown"
  step "Chờ khoảng 8 giây, mở lại Ubuntu, chạy lại wizard này."
  exit 0
fi
pause "Enter để sang stage tiếp"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Cài Docker Engine (apt repo chính thức)"
open_url "https://docs.docker.com/engine/install/ubuntu/"
if command -v docker >/dev/null 2>&1; then
  say "Docker đã có: $(docker --version 2>/dev/null || sudo docker --version)"
  confirm "Bỏ qua bước cài đặt?" && SKIP_INSTALL=1 || SKIP_INSTALL=0
else
  SKIP_INSTALL=0
fi
if [[ "$SKIP_INSTALL" == 0 ]]; then
  say "Sẽ chạy đúng các lệnh trong tài liệu Docker (cần sudo, hỏi mật khẩu của bạn):"
  note "  1) gỡ gói không chính thức xung đột   2) thêm apt repo + khoá GPG   3) cài docker-ce, compose plugin"
  confirm "Bắt đầu cài?" || exit 1
  # Gỡ gói xung đột (không sao nếu chưa cài gói nào)
  sudo apt remove $(dpkg --get-selections docker.io docker-compose docker-compose-v2 docker-doc docker-buildx podman-docker containerd runc 2>/dev/null | cut -f1) || true
  sudo apt update
  sudo apt install -y ca-certificates curl
  sudo install -m 0755 -d /etc/apt/keyrings
  sudo curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc
  sudo chmod a+r /etc/apt/keyrings/docker.asc
  sudo tee /etc/apt/sources.list.d/docker.sources >/dev/null <<EOF
Types: deb
URIs: https://download.docker.com/linux/ubuntu
Suites: $(. /etc/os-release && echo "${UBUNTU_CODENAME:-$VERSION_CODENAME}")
Components: stable
Architectures: $(dpkg --print-architecture)
Signed-By: /etc/apt/keyrings/docker.asc
EOF
  sudo apt update
  sudo apt install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
fi
say "Kiểm tra:"
sudo docker run --rm hello-world | head -5
confirm "Thấy dòng 'Hello from Docker!'?" || { warn "Docker chưa chạy đúng. Xem: sudo systemctl status docker"; exit 1; }

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Chạy docker không cần sudo, tự khởi động cùng systemd"
open_url "https://docs.docker.com/engine/install/linux-postinstall/"
sudo systemctl enable docker.service containerd.service
sudo systemctl start docker.service
getent group docker >/dev/null || sudo groupadd docker
sudo usermod -aG docker "$USER"
say "Đã thêm $USER vào nhóm docker."
if docker info >/dev/null 2>&1; then
  say "docker chạy không cần sudo ✓"
else
  warn "Phiên terminal này chưa nhận nhóm docker mới (cần mở lại terminal, hoặc chạy 'newgrp docker')."
  note "Wizard sẽ dùng 'sudo docker' cho phần còn lại của lần chạy này."
  DOCKER=(sudo docker)
  SKIPPED+=("Mở lại terminal Ubuntu (hoặc newgrp docker) để dùng docker không cần sudo")
fi
pause "Enter để sang stage tiếp"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Chạy cụm 3 broker (labs/03-cluster)"
[[ -f "$LAB_DIR/docker-compose.yml" ]] || { warn "Không thấy $LAB_DIR/docker-compose.yml"; exit 1; }
say "Thư mục: $LAB_DIR"
say "Lần đầu sẽ kéo image apache/kafka:4.4.0, có thể mất vài phút."
cd "$LAB_DIR"
"${DOCKER[@]}" compose up -d
say "Chờ cụm sẵn sàng (tối đa ~90 giây)..."
ready=0
for _ in $(seq 1 30); do
  if "${DOCKER[@]}" exec kafka-1 "$KT" --bootstrap-server "$BOOT" --list >/dev/null 2>&1; then ready=1; break; fi
  sleep 3
done
"${DOCKER[@]}" compose ps
if [[ "$ready" != 1 ]]; then
  warn "Cụm chưa trả lời. Xem log:  ${DOCKER[*]} compose logs --tail=50"
  confirm "Vẫn tiếp tục sang bước kiểm tra?" || exit 1
fi
confirm "Cả 3 container kafka-1/2/3 đang 'running'?" || exit 1

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Tạo topic, đọc --describe, kiểm tra tắt tự tạo topic"
topics="$("${DOCKER[@]}" exec kafka-1 "$KT" --bootstrap-server "$BOOT" --list || true)"
if grep -qx lab-orders <<<"$topics"; then
  say "Topic lab-orders đã có."
else
  "${DOCKER[@]}" exec kafka-1 "$KT" --bootstrap-server "$BOOT" \
    --create --topic lab-orders --partitions 3 --replication-factor 3 --config min.insync.replicas=2
fi
"${DOCKER[@]}" exec kafka-1 "$KT" --bootstrap-server "$BOOT" --describe --topic lab-orders
step "Mong đợi: 3 partition; mỗi dòng có Leader, Replicas gồm 3 broker, Isr gồm 3 broker; Configs có min.insync.replicas=2."
confirm "Đúng như mong đợi?" || SKIPPED+=("Cụm lab-orders chưa đúng mong đợi: xem labs/03-cluster/README.md")

say "Thử gửi vào topic KHÔNG tồn tại (phải lỗi nếu auto-create đã tắt); chờ tối đa 25 giây..."
echo "thu" | timeout 25 "${DOCKER[@]}" exec -i kafka-1 /opt/kafka/bin/kafka-console-producer.sh \
  --bootstrap-server "$BOOT" --topic khong-ton-tai >/dev/null 2>&1 || true
topics="$("${DOCKER[@]}" exec kafka-1 "$KT" --bootstrap-server "$BOOT" --list || true)"
if grep -qx khong-ton-tai <<<"$topics"; then
  warn "Topic 'khong-ton-tai' ĐÃ ĐƯỢC TẠO: biến KAFKA_AUTO_CREATE_TOPICS_ENABLE chưa có tác dụng."
  SKIPPED+=("Auto-create topic vẫn bật: báo lại để sửa docker-compose.yml (xoá topic: kafka-topics.sh --delete --topic khong-ton-tai)")
else
  say "Không có topic 'khong-ton-tai' ✓ (tắt tự tạo topic có tác dụng)"
fi
pause "Enter để sang stage tiếp"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Kết nối từ Windows tới cụm (localhost:29092)"
if (exec 3<>/dev/tcp/127.0.0.1/29092) 2>/dev/null; then
  say "Trong WSL, cổng 29092 mở ✓"
else
  warn "Trong WSL, cổng 29092 không mở."
fi
step "Mở Windows PowerShell (không phải Ubuntu) và chạy:"
note "    Test-NetConnection -ComputerName localhost -Port 29092"
note "    (lặp lại với cổng 39092 và 49092)"
step "Kết quả cần thấy: TcpTestSucceeded : True"
if confirm "Cả 3 cổng đều True?"; then
  say "Ứng dụng Spring chạy trên Windows dùng được localhost:29092,39092,49092 ✓"
else
  warn "Windows không thấy cổng. Theo tài liệu WSL, localhostForwarding mặc định là true nhưng bị bỏ qua khi networkingMode=mirrored."
  note "Nguồn: https://learn.microsoft.com/en-us/windows/wsl/wsl-config"
  SKIPPED+=("Windows chưa kết nối được localhost:29092: chạy lab Spring trong WSL, hoặc kiểm tra .wslconfig")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
say "Cụm đang chạy. Tiếp theo: lab 04 (labs/04-producer-durability)."
say "Dừng cụm:  cd labs/03-cluster && docker compose down   (thêm -v để xoá dữ liệu)"
}

run_wizard "$@"; exit
